```apex
/**
 * Transaction finalizer for ErpAccountSyncJob.
 *
 * Always writes exactly one FB_Job_Log__c row for the finished run and, when the
 * run failed and attempts remain, re-enqueues the job for the same accounts with
 * attempt + 1 (a maximum of 3 attempts).
 */
public with sharing class ErpSyncFinalizer implements Finalizer {

    private static final String JOB_NAME       = 'ErpAccountSyncJob';
    private static final String STATUS_SUCCESS = 'Success';
    private static final String STATUS_FAILED  = 'Failed';

    /** Stop retrying once this attempt number has been reached. */
    private static final Integer MAX_ATTEMPTS     = 3;
    /** Error__c is a Text(255) field - never send more than it can hold. */
    private static final Integer MAX_ERROR_LENGTH = 255;

    /** The accounts the finished run was working on (also used for the retry). */
    private final Set<Id> accountIds;

    /** The attempt number this run represents (1-based). */
    private final Integer attempt;

    public ErpSyncFinalizer(Set<Id> accountIds, Integer attempt) {
        this.accountIds = (accountIds == null) ? new Set<Id>() : new Set<Id>(accountIds);
        this.attempt    = (attempt == null || attempt < 1) ? 1 : attempt;
    }

    public void execute(FinalizerContext context) {
        final Boolean succeeded = isSuccessful(context);

        FB_Job_Log__c jobLog = new FB_Job_Log__c(
            Job_Name__c = JOB_NAME,
            Attempt__c  = attempt,
            Status__c   = succeeded ? STATUS_SUCCESS : STATUS_FAILED
        );

        if (!succeeded) {
            jobLog.Error__c = truncateToFieldLength(errorMessage(context));
        }

        // Exactly one log row per run, written whatever happened in the job.
        insert jobLog;

        // Retry only after a failure and only while attempts remain (1 -> 2 -> 3).
        if (!succeeded && attempt < MAX_ATTEMPTS) {
            System.enqueueJob(new ErpAccountSyncJob(accountIds, attempt + 1));
        }
    }

    /**
     * Determines whether the finished run succeeded.
     *
     * The outcome is taken from the finalizer result and from the exception the
     * job left behind; either one alone is enough to prove a failure.
     */
    private static Boolean isSuccessful(FinalizerContext context) {
        if (context == null) {
            return true;
        }

        // A recorded exception always means the run failed.
        if (context.getException() != null) {
            return false;
        }

        final String resultName = resultNameOf(context);
        if (resultName == null) {
            // No recognisable result value - nothing failed.
            return true;
        }

        final String normalized = resultName.toLowerCase();
        if (normalized.contains('unhandled')
                || normalized.contains('fail')
                || normalized.contains('error')) {
            return false;
        }

        return true;
    }

    /** @return The finalizer result as text, or null when it is not available. */
    private static String resultNameOf(FinalizerContext context) {
        if (context == null) {
            return null;
        }
        final String value = String.valueOf(context.getResult());
        return (value == null || value == 'null') ? null : value;
    }

    /** @return The message of the job's exception, or null when there is none. */
    private static String errorMessage(FinalizerContext context) {
        if (context == null) {
            return null;
        }
        final Exception jobException = context.getException();
        return (jobException == null) ? null : jobException.getMessage();
    }

    /** Cuts the message down to the 255 characters Error__c can hold. */
    private static String truncateToFieldLength(String value) {
        if (value == null) {
            return null;
        }
        return (value.length() > MAX_ERROR_LENGTH)
            ? value.substring(0, MAX_ERROR_LENGTH)
            : value;
    }
}
