```apex
/**
 * Keeps Account.FB_Open_Pipeline__c (sum of Amount of open opportunities) and
 * Account.FB_Open_Opportunities__c (count of open opportunities) correct.
 *
 * Design notes:
 *  - Recalculation always re-reads the current database state with a single
 *    grouped aggregate query, so any number of DML statements in one transaction
 *    (Flow then Apex, several test DML statements, ...) leave correct totals,
 *    and each handler run is idempotent.
 *  - The account set includes both the new and the old AccountId, so a move to
 *    another account updates BOTH accounts.
 *  - An Account is only written when its stored values actually differ from the
 *    freshly computed ones. This keeps "0 and 0, not blank" (blank counts as
 *    changed) while guaranteeing termination against the legacy AccountTrigger,
 *    which rewrites every open Opportunity on every Account update (our second
 *    pass finds nothing to change, so the recursion stops).
 *  - `without sharing` so the roll-up counts every opportunity of the account,
 *    regardless of the running user's record access.
 *  - Bulk-safe: 1 aggregate query + 1 account query + 1 DML statement, no
 *    per-record SOQL/DML in loops (handles 200-record loads).
 */
public without sharing class OpportunityPipelineHandler {

    /**
     * Entry point. Safe to call with either list null (insert has no Trigger.old,
     * delete has no Trigger.new).
     *
     * @param newRecords Trigger.new (null on delete)
     * @param oldRecords Trigger.old (null on insert / undelete)
     */
    public static void recalculateOpenPipeline(List<Opportunity> newRecords, List<Opportunity> oldRecords) {
        Set<Id> accountIds = new Set<Id>();
        collectAccountIds(newRecords, accountIds);
        collectAccountIds(oldRecords, accountIds);

        if (accountIds.isEmpty()) {
            return;
        }

        // Single grouped aggregate over the current state of the database.
        Map<Id, Decimal> pipelineByAccount = new Map<Id, Decimal>();
        Map<Id, Integer> openCountByAccount = new Map<Id, Integer>();

        for (AggregateResult ar : [
            SELECT AccountId, SUM(Amount) totalAmount, COUNT(Id) openCount
            FROM Opportunity
            WHERE AccountId IN :accountIds
              AND IsClosed = false
            GROUP BY AccountId
        ]) {
            Id accountId = (Id) ar.get('AccountId');
            Decimal total = (Decimal) ar.get('totalAmount');
            pipelineByAccount.put(accountId, total == null ? 0 : total);
            openCountByAccount.put(accountId, (Integer) ar.get('openCount'));
        }

        List<Account> accountsToUpdate = new List<Account>();

        // Every touched account is loaded, including those that no longer have any
        // open opportunity: they are absent from the aggregate result and therefore
        // get 0 / 0 instead of being left untouched (or blank).
        for (Account account : [
            SELECT Id, FB_Open_Pipeline__c, FB_Open_Opportunities__c
            FROM Account
            WHERE Id IN :accountIds
        ]) {
            Decimal targetPipeline = pipelineByAccount.containsKey(account.Id)
                ? pipelineByAccount.get(account.Id)
                : 0;
            Decimal targetCount = openCountByAccount.containsKey(account.Id)
                ? Decimal.valueOf(openCountByAccount.get(account.Id))
                : 0;

            Boolean pipelineChanged = account.FB_Open_Pipeline__c == null
                || account.FB_Open_Pipeline__c != targetPipeline;
            Boolean countChanged = account.FB_Open_Opportunities__c == null
                || account.FB_Open_Opportunities__c != targetCount;

            if (pipelineChanged || countChanged) {
                accountsToUpdate.add(new Account(
                    Id = account.Id,
                    FB_Open_Pipeline__c = targetPipeline,
                    FB_Open_Opportunities__c = targetCount
                ));
            }
        }

        if (!accountsToUpdate.isEmpty()) {
            // One bulk DML statement for the whole transaction batch.
            update accountsToUpdate;
        }
    }

    private static void collectAccountIds(List<Opportunity> records, Set<Id> accountIds) {
        if (records == null) {
            return;
        }
        for (Opportunity opportunity : records) {
            if (opportunity.AccountId != null) {
                accountIds.add(opportunity.AccountId);
            }
        }
    }
}
