	public Opportunities(List<Opportunity> sObjectList)
	{
		super(sObjectList);
	}

	public Opportunities(List<Opportunity> sObjectList, SObjectType sObjectType)
	{
		super(sObjectList, sObjectType);
	}

	public override void onAfterInsert()
	{
		Set<Id> opportunityIds = new Set<Id>();
		for (Opportunity opportunity : (List<Opportunity>) Records)
		{
			if (isNewlyClosedWon(opportunity, null))
			{
				opportunityIds.add(opportunity.Id);
			}
		}
		startFulfilment(opportunityIds);
	}

	public override void onAfterUpdate(Map<Id, SObject> existing)
	{
		Set<Id> opportunityIds = new Set<Id>();
		for (Opportunity opportunity : (List<Opportunity>) Records)
		{
			Opportunity existingOpportunity = (Opportunity) existing.get(opportunity.Id);
			if (isNewlyClosedWon(opportunity, existingOpportunity))
			{
				opportunityIds.add(opportunity.Id);
			}
		}
		startFulfilment(opportunityIds);
	}

	private static Boolean isNewlyClosedWon(Opportunity current, Opportunity existing)
	{
		if (current.StageName != 'Closed Won')
		{
			return false;
		}
		return existing == null || existing.StageName != 'Closed Won';
	}

	private static void startFulfilment(Set<Id> opportunityIds)
	{
		if (opportunityIds.isEmpty())
		{
			return;
		}
		IOpportunityFulfilmentService service =
			(IOpportunityFulfilmentService) Application.Service.newInstance(
				IOpportunityFulfilmentService.class
			);
		service.startFulfilment(opportunityIds);
	}

	public class Constructor implements fflib_SObjectDomain.IConstructable
	{
		public fflib_SObjectDomain construct(List<SObject> sObjectList)
		{
			return new Opportunities(sObjectList);
		}
	}
}
