public class Opportunities extends fflib_SObjectDomain
{
	private static final String STAGE_CLOSED_WON = 'Closed Won';

	public Opportunities(List<Opportunity> sObjectList)
	{
		super(sObjectList);
	}

	public class Constructor implements fflib_SObjectDomain.IConstructable
	{
		public fflib_SObjectDomain construct(List<SObject> sObjectList)
		{
			return new Opportunities(sObjectList);
		}
	}

	/**
	 * Domain validation rules.
	 *
	 * 1. On insert and on update, Amount must not be negative.
	 * 2. On update, an opportunity whose StageName was already 'Closed Won' before the
	 *    update cannot have its Amount changed. An opportunity that is closed as won in
	 *    the very same update is allowed to change its Amount, because its previous stage
	 *    was not 'Closed Won'.
	 *
	 * Each rule is evaluated per record and raises its error on the Amount field of the
	 * offending record only (via the domain error(message, record, field) helper, which
	 * also records the failure in fflib_SObjectDomain.Errors for unit tests), so the
	 * remaining records of the same DML still save. The rules are bulk safe and need no SOQL.
	 */
	public override void onValidate()
	{
		// Rule 1 applies to insert and update. Outside of a trigger context (domain driven
		// directly, e.g. from a unit test) treat the invocation as insert-like usage.
		Boolean validateAmount = !Trigger.isExecuting || Trigger.isInsert || Trigger.isUpdate;
		// Rule 2 only exists on update: previous field values are only available there.
		Boolean isUpdate = Trigger.isExecuting && Trigger.isUpdate;
		Map<Id, SObject> oldRecords = isUpdate ? Trigger.oldMap : null;

		for (SObject so : Records)
		{
			Opportunity record = (Opportunity) so;

			// Rule 1 - Amount must not be negative (insert and update)
			if (validateAmount && record.Amount != null && record.Amount < 0)
			{
				error('Amount cannot be negative.', record, Opportunity.Amount);
			}

			// Rule 2 - Amount cannot change on an opportunity that was already won
			if (oldRecords == null)
			{
				continue;
			}

			SObject oldSo = oldRecords.get(record.Id);
			if (oldSo == null)
			{
				continue;
			}
			Opportunity oldRecord = (Opportunity) oldSo;

			if (oldRecord.StageName == STAGE_CLOSED_WON && oldRecord.Amount != record.Amount)
			{
				error('Amount cannot change on a won opportunity.', record, Opportunity.Amount);
			}
		}
	}
}
