public inherited sharing class AccountsSelector extends fflib_SObjectSelector
{
	/**
	 * The selector's data access setting.
	 *
	 * Every query issued by this selector is executed with this AccessLevel, i.e. it
	 * behaves as if the SOQL had been written WITH USER_MODE: the platform (not Apex)
	 * enforces the running user's object access, field-level security and sharing
	 * rules. A user who is not allowed to read one of the selected fields receives a
	 * QueryException instead of silently missing/blank data.
	 */
	private final AccessLevel dataAccessLevel;

	/**
	 * No-argument constructor used by the Application selector factory.
	 * All defaults are applied here: the Credit_Review field set fields are always
	 * part of every query and every query runs in user mode.
	 */
	public AccountsSelector()
	{
		this(AccessLevel.USER_MODE);
	}

	/**
	 * Constructor allowing an explicit data access setting.
	 */
	public AccountsSelector(AccessLevel dataAccessLevel)
	{
		super();
		this.dataAccessLevel = dataAccessLevel;
	}

	public Schema.SObjectType getSObjectType()
	{
		return Account.SObjectType;
	}

	/**
	 * Base field list: Id, Name, Industry.
	 *
	 * The members of the Credit_Review field set are resolved dynamically from the
	 * field set metadata at runtime - they are never hard-coded - so admins can add
	 * or remove fields from the field set without any code change.
	 */
	public List<Schema.SObjectField> getSObjectFieldList()
	{
		List<Schema.SObjectField> fields = new List<Schema.SObjectField>{
			Account.Id,
			Account.Name,
			Account.Industry
		};

		// Append the Credit_Review field set fields, skipping duplicates (an admin
		// could add Name or Id to the field set).
		Set<Schema.SObjectField> alreadySelected = new Set<Schema.SObjectField>(fields);
		for (Schema.SObjectField creditReviewField : getCreditReviewFieldSetFields())
		{
			if (creditReviewField != null && !alreadySelected.contains(creditReviewField))
			{
				fields.add(creditReviewField);
				alreadySelected.add(creditReviewField);
			}
		}

		return fields;
	}

	/**
	 * Selects the Accounts with the given Ids (base fields + Credit_Review field set
	 * fields) in user mode.
	 */
	public List<Account> selectById(Set<Id> accountIds)
	{
		return queryAccounts(accountIds, false);
	}

	/**
	 * Selects the Accounts with the given Ids together with their Contacts child
	 * records in a single query. The sub-select is built from ContactsSelector so it
	 * always uses that selector's fields. The WITH USER_MODE access level applies to
	 * the parent and to the subquery.
	 */
	public List<Account> selectByIdWithContacts(Set<Id> accountIds)
	{
		return queryAccounts(accountIds, true);
	}

	/**
	 * Resolves the current members of the Credit_Review field set to SObjectFields.
	 * Reads the metadata at runtime so field set changes need no deployment.
	 */
	private static List<Schema.SObjectField> getCreditReviewFieldSetFields()
	{
		List<Schema.SObjectField> fields = new List<Schema.SObjectField>();

		Map<String, Schema.SObjectField> fieldMap =
			Account.SObjectType.getDescribe().fields.getMap();

		for (Schema.FieldSetMember member
			: Schema.SObjectType.Account.fieldSets.Credit_Review.getFields())
		{
			String apiName = member.getField();

			// Describe maps are keyed by lower-case API names; try both spellings.
			Schema.SObjectField field = fieldMap.get(apiName);
			if (field == null)
			{
				field = fieldMap.get(apiName.toLowerCase());
			}
			if (field != null)
			{
				fields.add(field);
			}
		}

		return fields;
	}

	/**
	 * Builds and executes the Account query in the selector's configured data
	 * access mode (user mode by default).
	 */
	private List<Account> queryAccounts(Set<Id> accountIds, Boolean includeContacts)
	{
		if (accountIds == null || accountIds.isEmpty())
		{
			return new List<Account>();
		}

		String queryString =
			'SELECT ' + String.join(toFieldNames(getSObjectFieldList()), ', ');

		if (includeContacts)
		{
			// Sub-query over the Contacts child relationship, field list taken from
			// ContactsSelector so both selectors stay in sync automatically.
			queryString +=
				', (SELECT ' +
				String.join(toFieldNames(new ContactsSelector().getSObjectFieldList()), ', ') +
				' FROM Contacts)';
		}

		queryString += ' FROM Account WHERE Id IN :accountIds';

		// queryWithBinds(...) with AccessLevel.USER_MODE == SOQL WITH USER_MODE:
		// object, field and sharing access are enforced by the platform and a
		// violation raises an exception instead of returning data.
		return (List<Account>) Database.queryWithBinds(
			queryString,
			new Map<String, Object>{ 'accountIds' => accountIds },
			dataAccessLevel
		);
	}

	private static List<String> toFieldNames(List<Schema.SObjectField> fields)
	{
		List<String> fieldNames = new List<String>();
		for (Schema.SObjectField field : fields)
		{
			fieldNames.add(field.getDescribe().getName());
		}
		return fieldNames;
	}
}
