public class OpportunityWinService
{
	public static Integer markWon(Set<Id> opportunityIds)
	{
		if (opportunityIds == null || opportunityIds.isEmpty())
		{
			return 0;
		}

		List<Opportunity> opportunities =
			OpportunitiesSelector.newInstance().selectById(opportunityIds);

		if (opportunities == null || opportunities.isEmpty())
		{
			return 0;
		}

		Date today = Date.today();
		List<Opportunity> toClose = new List<Opportunity>();

		for (Opportunity opportunity : opportunities)
		{
			if (opportunity == null || opportunity.Id == null)
			{
				continue;
			}
			if ('Closed Won'.equals(opportunity.StageName))
			{
				continue;
			}
			opportunity.StageName = 'Closed Won';
			opportunity.CloseDate = today;
			toClose.add(opportunity);
		}

		if (toClose.isEmpty())
		{
			return 0;
		}

		fflib_ISObjectUnitOfWork uow = Application.UnitOfWork.newInstance();

		for (Opportunity opportunity : toClose)
		{
			uow.registerDirty(opportunity);
			uow.registerNew(
				new Deal_Won__e(
					Opportunity_Id__c = String.valueOf(opportunity.Id),
					Amount__c = opportunity.Amount
				)
			);
		}

		uow.commitWork();

		return toClose.size();
	}
}
