import { LightningElement, api, wire } from 'lwc';
import { getRecord } from 'lightning/uiRecordApi';

import NAME_FIELD from '@salesforce/schema/Account.Name';
import INDUSTRY_FIELD from '@salesforce/schema/Account.Industry';
import ANNUAL_REVENUE_FIELD from '@salesforce/schema/Account.AnnualRevenue';
import OWNER_NAME_FIELD from '@salesforce/schema/Account.Owner.Name';

// The four fields the record page header needs.
const ACCOUNT_FIELDS = [
    NAME_FIELD,
    INDUSTRY_FIELD,
    ANNUAL_REVENUE_FIELD,
    OWNER_NAME_FIELD
];

export default class AccountHeader extends LightningElement {
    /**
     * Public property supplied by the record page (or reused console tab).
     * It is reactive: when recordId changes, the getRecord wire re-executes
     * and the component reloads the new Account automatically.
     */
    @api recordId;

    record;
    error;

    @wire(getRecord, {
        recordId: '$recordId',
        fields: ACCOUNT_FIELDS
    })
    wiredAccount({ data, error }) {
        if (data) {
            this.record = data;
            this.error = undefined;
        } else if (error) {
            this.error = error;
            this.record = undefined;
        }
    }

    // ---- State helpers --------------------------------------------------

    // Still loading: neither data nor error received yet.
    get isLoading() {
        return !this.record && !this.error;
    }

    get hasRecord() {
        return !!this.record;
    }

    get hasError() {
        return !!this.error;
    }

    get errorMessage() {
        if (this.error && this.error.body && this.error.body.message) {
            return this.error.body.message;
        }
        return '';
    }

    // ---- Field accessors ------------------------------------------------

    get name() {
        return this.getFieldValue(NAME_FIELD);
    }

    get industry() {
        return this.getFieldValue(INDUSTRY_FIELD);
    }

    get hasIndustry() {
        const value = this.industry;
        return value !== undefined && value !== null && value !== '';
    }

    get revenue() {
        return this.getFieldValue(ANNUAL_REVENUE_FIELD);
    }

    get ownerName() {
        return this.getFieldValue(OWNER_NAME_FIELD);
    }

    /**
     * Reads a field value from the wired record. Returns undefined when the
     * record has not loaded or the (optional) field has no value, so the
     * template can guard with if:true / if:false directives safely.
     */
    getFieldValue(fieldApiName) {
        if (!this.record || !this.record.fields) {
            return undefined;
        }
        const field = this.record.fields[fieldApiName];
        if (field && field.value !== undefined) {
            return field.value;
        }
        return undefined;
    }
}
