import { LightningElement, api, wire } from 'lwc';
import getContacts from '@salesforce/apex/ContactController.getContacts';
import { updateRecord, refreshApex } from 'lightning/uiRecordApi';
import { ShowToastEvent } from 'lightning/platformShowToastEvent';

const COLUMNS = [
    { label: 'Name', fieldName: 'Name', type: 'text' },
    { label: 'Title', fieldName: 'Title', type: 'text', editable: true },
    { label: 'Phone', fieldName: 'Phone', type: 'phone', editable: true },
    { label: 'Email', fieldName: 'Email', type: 'email', editable: true }
];

// Safely extract a user-facing message from an error/failure of any shape.
function getErrorMessage(error) {
    if (error && error.body && typeof error.body.message === 'string' && error.body.message) {
        return error.body.message;
    }
    if (error && typeof error.message === 'string' && error.message) {
        return error.message;
    }
    if (typeof error === 'string' && error) {
        return error;
    }
    return 'An unexpected error occurred.';
}

export default class AccountContactsTable extends LightningElement {
    @api recordId;

    columns = COLUMNS;
    draftValues = [];

    // Keep the wired result so it can be passed to refreshApex
    wiredContacts;

    @wire(getContacts, { accountId: '$recordId' })
    wiredGetContacts(result) {
        this.wiredContacts = result;
    }

    get contacts() {
        if (this.wiredContacts && this.wiredContacts.data) {
            return this.wiredContacts.data;
        }
        return [];
    }

    handleSave(event) {
        const drafts = (event.detail && event.detail.draftValues) || [];

        // One updateRecord call per draft row, fired in parallel.
        // Each promise is normalised to { success, error } so Promise.all waits
        // for every call to settle and we can inspect the outcome uniformly.
        const updatePromises = drafts.map((draft) => {
            try {
                return Promise.resolve(updateRecord({ fields: { ...draft } }))
                    .then(() => ({ success: true }))
                    .catch((error) => ({ success: false, error: error }));
            } catch (error) {
                return Promise.resolve({ success: false, error: error });
            }
        });

        Promise.all(updatePromises)
            .then((results) => {
                const failure = results.find(
                    (result) => result && result.success === false
                );

                if (failure) {
                    // Any failure: error toast only - no refresh, no success toast.
                    this.showErrorToast(failure.error);
                    return;
                }

                // All succeeded.
                this.dispatchEvent(
                    new ShowToastEvent({
                        variant: 'success',
                        title: 'Contacts updated'
                    })
                );
                this.draftValues = [];
                this.refreshWireData();
            })
            .catch((error) => {
                // Safety net so an unexpected error never becomes an unhandled
                // rejection / crashes the component.
                this.showErrorToast(error);
            });
    }

    refreshWireData() {
        try {
            const refreshed = refreshApex(this.wiredContacts);
            if (refreshed && typeof refreshed.catch === 'function') {
                // A refresh failure must not surface as a save error toast.
                refreshed.catch(() => {});
            }
        } catch (error) {
            // Records were already saved; ignore refresh failures.
        }
    }

    showErrorToast(error) {
        this.dispatchEvent(
            new ShowToastEvent({
                variant: 'error',
                title: 'Could not save contacts',
                message: getErrorMessage(error)
            })
        );
    }
}
