/**
 * EmployerService
 *
 * Keeps each donor's current employer (an existing Organization Account) in
 * sync on the Contact, using NPSP Affiliations (Household Account model).
 *
 * For every contact in the map the call guarantees afterwards:
 *   - a Current, primary affiliation (npe5__Primary__c = true) between the
 *     contact and the organization;
 *   - Contact.npsp__Primary_Affiliation__c points at that organization;
 *   - the previous primary employer is retired: non-primary, Status = 'Former',
 *     npe5__EndDate__c = today (this is also what NPSP maintains through its
 *     standard "primary affiliation" mechanism, so both agree);
 *   - the contact's AccountId (its household) is never touched;
 *   - if the organization is already the contact's primary affiliation,
 *     nothing is written at all - no duplicate affiliation row.
 *
 * A null or empty input map does nothing.
 *
 * Limits for one call with 200 contacts (this class's own statements):
 *   SOQL queries    : 2
 *   DML statements  : 2  (1 upsert of Affiliations + 1 update of Contacts)
 */
public without sharing class EmployerService {

    private static final String STATUS_CURRENT = 'Current';
    private static final String STATUS_FORMER  = 'Former';

    /**
     * Points every Contact in the map at the given Organization Account as its
     * current, primary employer.
     *
     * @param employerByContactId Contact Id -> Organization Account Id
     */
    public static void setCurrentEmployers(Map<Id, Id> employerByContactId) {

        // Null / empty input does nothing.
        if (employerByContactId == null || employerByContactId.isEmpty()) {
            return;
        }

        // Normalise the input: ignore null keys and null employers.
        Map<Id, Id> contactToEmployer = new Map<Id, Id>();
        for (Id contactId : employerByContactId.keySet()) {
            Id employerId = employerByContactId.get(contactId);
            if (contactId != null && employerId != null) {
                contactToEmployer.put(contactId, employerId);
            }
        }
        if (contactToEmployer.isEmpty()) {
            return;
        }
        Set<Id> contactIds = contactToEmployer.keySet();

        // ---------------------------------------------------------------------
        // SOQL 1 of 2 : the contacts (only the field this class may write).
        // ---------------------------------------------------------------------
        Map<Id, Contact> contactsById = new Map<Id, Contact>(
            [
                SELECT Id, npsp__Primary_Affiliation__c
                  FROM Contact
                 WHERE Id IN :contactIds
            ]
        );
        if (contactsById.isEmpty()) {
            return;
        }

        // ---------------------------------------------------------------------
        // SOQL 2 of 2 : every affiliation of those contacts. One query gives us
        // both the existing contact/employer row (so we never create a
        // duplicate) and the current primary affiliation (so we can retire it).
        // ---------------------------------------------------------------------
        List<npe5__Affiliation__c> existingAffiliations = [
            SELECT Id, npe5__Contact__c, npe5__Organization__c, npe5__Status__c,
                   npe5__Primary__c, npe5__StartDate__c, npe5__EndDate__c,
                   npe5__Role__c
              FROM npe5__Affiliation__c
             WHERE npe5__Contact__c IN :contactIds
        ];

        // Index the affiliations (no queries inside the loop below).
        Map<String, npe5__Affiliation__c> rowByContactAndEmployer =
            new Map<String, npe5__Affiliation__c>();
        Map<Id, List<npe5__Affiliation__c>> primaryRowsByContactId =
            new Map<Id, List<npe5__Affiliation__c>>();

        for (npe5__Affiliation__c affiliation : existingAffiliations) {
            rowByContactAndEmployer.put(
                pairKey(affiliation.npe5__Contact__c, affiliation.npe5__Organization__c),
                affiliation
            );
            if (affiliation.npe5__Primary__c == true) {
                List<npe5__Affiliation__c> primaries =
                    primaryRowsByContactId.get(affiliation.npe5__Contact__c);
                if (primaries == null) {
                    primaries = new List<npe5__Affiliation__c>();
                    primaryRowsByContactId.put(affiliation.npe5__Contact__c, primaries);
                }
                primaries.add(affiliation);
            }
        }

        List<npe5__Affiliation__c> affiliationsToUpsert =
            new List<npe5__Affiliation__c>();
        List<Contact> contactsToUpdate = new List<Contact>();
        Date todayDate = Date.today();

        for (Id contactId : contactToEmployer.keySet()) {

            Contact donor = contactsById.get(contactId);
            if (donor == null) {
                continue;                                   // contact no longer exists
            }

            Id employerId = contactToEmployer.get(contactId);

            // Existing contact/employer row, if any - it is re-used so that we
            // can never create a duplicate affiliation.
            npe5__Affiliation__c employerRow =
                rowByContactAndEmployer.get(pairKey(contactId, employerId));

            // Is this organization already the contact's primary affiliation?
            Boolean primaryRowExists = false;
            List<npe5__Affiliation__c> currentPrimaries =
                primaryRowsByContactId.get(contactId);
            if (currentPrimaries != null) {
                for (npe5__Affiliation__c primaryRow : currentPrimaries) {
                    if (primaryRow.npe5__Organization__c == employerId) {
                        primaryRowExists = true;
                        break;
                    }
                }
            }
            // Already primary (flag set), or already the contact's primary
            // affiliation per the Contact lookup while a row exists:
            // nothing changes, no duplicate affiliation is written.
            if (primaryRowExists) {
                continue;
            }
            if (employerRow != null &&
                donor.npsp__Primary_Affiliation__c == employerId) {
                continue;
            }

            // --- Current, primary employer affiliation ---------------------------
            if (employerRow == null) {
                // Brand new affiliation (inserted by the upsert below).
                employerRow = new npe5__Affiliation__c(
                    npe5__Contact__c      = contactId,
                    npe5__Organization__c = employerId,
                    npe5__StartDate__c    = todayDate
                );
            } else {
                // Re-use the existing row: no duplicate affiliation.
                if (employerRow.npe5__StartDate__c == null) {
                    employerRow.npe5__StartDate__c = todayDate;
                }
                employerRow.npe5__EndDate__c = null;        // reopen a Former row
            }
            employerRow.npe5__Status__c  = STATUS_CURRENT;
            employerRow.npe5__Primary__c = true;
            affiliationsToUpsert.add(employerRow);

            // --- Retire the previous primary employer(s) -------------------------
            // Former, non-primary, ended today (the state NPSP maintains when a
            // new primary affiliation is created through its standard mechanism).
            if (currentPrimaries != null) {
                for (npe5__Affiliation__c previousPrimary : currentPrimaries) {
                    if (previousPrimary.npe5__Organization__c == employerId) {
                        continue;                           // never retire the new employer
                    }
                    previousPrimary.npe5__Primary__c = false;
                    previousPrimary.npe5__Status__c  = STATUS_FORMER;
                    previousPrimary.npe5__EndDate__c  = todayDate;
                    affiliationsToUpsert.add(previousPrimary);
                }
            }

            // --- Contact's primary affiliation lookup ----------------------------
            // Only this field is written; AccountId (the household) is untouched.
            donor.npsp__Primary_Affiliation__c = employerId;
            contactsToUpdate.add(donor);
        }

        // DML 1 of 2 : one statement handles both inserts (new rows have no Id)
        // and updates (existing rows carry an Id).
        if (!affiliationsToUpsert.isEmpty()) {
            upsert affiliationsToUpsert;
        }
        // DML 2 of 2 : point the Contacts at their new primary affiliation.
        if (!contactsToUpdate.isEmpty()) {
            update contactsToUpdate;
        }
    }

    /** Stable key for a contact/organization pair. */
    private static String pairKey(Id contactId, Id organizationId) {
        return String.valueOf(contactId) + '|' + String.valueOf(organizationId);
    }
}
