/**
 * Stages one-off web gifts as NPSP Data Import records and processes them
 * synchronously through NPSP's own import engine (BDI), so that NPSP's contact
 * matching, householding and donation processing rules apply and every staged
 * record remains in the org as the audit trail of the import.
 *
 * Bulk safe: one DML statement for staging, one call to NPSP's Apex import API,
 * one query to read back the results. Safe for 200+ gifts per invocation and
 * does not rely on a single row succeeding for the batch to complete.
 */
public with sharing class GiftImportService {

    /** One gift received from the website. */
    public class WebGift {
        public String firstName;
        public String lastName;
        public String email;        // the donor's personal email
        public Decimal amount;
        public Date giftDate;
    }

    /** The outcome for a single gift, mirroring the processed Data Import row. */
    public class ImportResult {
        public Boolean success;
        public Id contactId;        // the matched or created contact
        public Id opportunityId;    // the created donation
        public String errorMessage; // NPSP's failure information when success is false
    }

    private static final String STATUS_NEW = 'New';
    private static final String STATUS_IMPORTED = 'Imported';
    private static final String DONOR_CONTACT1 = 'Contact1';

    /**
     * Stages and processes the supplied gifts through NPSP's Data Importer.
     *
     * @param gifts the gifts to import; may be null or empty
     * @return one ImportResult per gift, in input order; empty list for null/empty input
     */
    public static List<ImportResult> importGifts(List<WebGift> gifts) {
        List<ImportResult> results = new List<ImportResult>();

        // Null or empty input -> empty list, no work performed.
        if (gifts == null || gifts.isEmpty()) {
            return results;
        }

        // Results are addressed by input index so the response order always
        // matches the request order, independently of DML/query ordering.
        ImportResult[] resultsByIndex = new ImportResult[gifts.size()];

        List<npsp__DataImport__c> rowsToInsert = new List<npsp__DataImport__c>();
        List<Integer> rowToGiftIndex = new List<Integer>();

        for (Integer i = 0; i < gifts.size(); i++) {
            WebGift gift = gifts[i];
            if (gift == null) {
                resultsByIndex[i] = buildFailure('The gift payload was null.');
                continue;
            }

            rowsToInsert.add(new npsp__DataImport__c(
                npsp__Status__c = STATUS_NEW,
                npsp__Contact1_Firstname__c = gift.firstName,
                npsp__Contact1_Lastname__c = gift.lastName,
                npsp__Contact1_Personal_Email__c = gift.email,
                npsp__Donation_Amount__c = gift.amount,
                npsp__Donation_Date__c = gift.giftDate,
                npsp__Donation_Donor__c = DONOR_CONTACT1
            ));
            rowToGiftIndex.add(i);
        }

        if (!rowsToInsert.isEmpty()) {
            stageAndProcess(rowsToInsert, rowToGiftIndex, resultsByIndex);
        }

        // Flatten back into a single list in the original input order.
        for (Integer i = 0; i < gifts.size(); i++) {
            results.add(resultsByIndex[i]);
        }
        return results;
    }

    /**
     * Inserts the staged rows, runs NPSP's import API over them and maps the
     * outcome of each row back to its gift. A row NPSP rejects never aborts the
     * remaining rows: staging uses allOrFalse and BDI records per-row failures
     * in npsp__FailureInformation__c rather than throwing.
     */
    private static void stageAndProcess(
        List<npsp__DataImport__c> rowsToInsert,
        List<Integer> rowToGiftIndex,
        ImportResult[] resultsByIndex
    ) {
        // Single DML statement for the whole batch; a row that fails staging
        // (validation rule, bad data) must not roll back the other staged rows.
        List<Database.SaveResult> saveResults = Database.insert(rowsToInsert, false);

        List<Id> stagedIds = new List<Id>();
        for (Integer j = 0; j < saveResults.size(); j++) {
            Database.SaveResult sr = saveResults[j];
            Integer giftIndex = rowToGiftIndex[j];
            if (sr.isSuccess()) {
                stagedIds.add(sr.getId());
            } else {
                resultsByIndex[giftIndex] = buildFailure(describeErrors(sr.getErrors()));
            }
        }

        if (stagedIds.isEmpty()) {
            return;
        }

        // Process all staged rows synchronously, in this transaction, using the
        // org's Data Import settings (npsp__Data_Import_Settings__c) for
        // contact matching and donation handling.
        String engineError;
        try {
            npsp.BDI_API.importData();
        } catch (Exception ex) {
            // If NPSP's engine fails as a whole, report it per row instead of
            // failing the entire call; the staged rows stay as the audit trail.
            engineError = ex.getMessage();
        }

        // One query to read back NPSP's results for exactly our staged rows.
        Map<Id, npsp__DataImport__c> processedRows = new Map<Id, npsp__DataImport__c>(
            [
                SELECT Id,
                       npsp__Status__c,
                       npsp__Contact1Imported__c,
                       npsp__DonationImported__c,
                       npsp__FailureInformation__c
                  FROM npsp__DataImport__c
                 WHERE Id IN :stagedIds
            ]
        );

        for (Integer j = 0; j < stagedIds.size(); j++) {
            Id stagedId = stagedIds[j];
            Integer giftIndex = rowToGiftIndex[rowsToInsert.size() > 0
                ? indexOfRowWithId(rowsToInsert, stagedId) : 0];
            // The staged rows keep insertion order, so match by position.
        }

        // Positional mapping: stagedIds is in the same relative order as the
        // successfully inserted rows, so walk the original rows and pair them up.
        Integer stagedPosition = 0;
        for (Integer j = 0; j < rowsToInsert.size(); j++) {
            Id rowId = rowsToInsert[j].Id;
            if (rowId == null) {
                continue; // staging failed for this row; already reported
            }
            Integer giftIndex = rowToGiftIndex[j];
            npsp__DataImport__c di = processedRows.get(rowId);

            if (di == null) {
                resultsByIndex[giftIndex] = buildFailure(
                    'The staged Data Import record could not be read back.'
                );
                continue;
            }

            if (STATUS_IMPORTED.equals(di.npsp__Status__c)) {
                ImportResult res = new ImportResult();
                res.success = true;
                res.contactId = di.npsp__Contact1Imported__c;
                res.opportunityId = di.npsp__DonationImported__c;
                res.errorMessage = null;
                resultsByIndex[giftIndex] = res;
            } else {
                String message = di.npsp__FailureInformation__c;
                if (String.isBlank(message)) {
                    message = String.isBlank(engineError)
                        ? 'NPSP did not import this gift (status: ' + di.npsp__Status__c + ').'
                        : engineError;
                }
                resultsByIndex[giftIndex] = buildFailure(message);
            }
            stagedPosition++;
        }
    }

    private static Integer indexOfRowWithId(List<npsp__DataImport__c> rows, Id recordId) {
        for (Integer k = 0; k < rows.size(); k++) {
            if (rows[k].Id == recordId) {
                return k;
            }
        }
        return 0;
    }

    private static ImportResult buildFailure(String message) {
        ImportResult res = new ImportResult();
        res.success = false;
        res.contactId = null;
        res.opportunityId = null;
        res.errorMessage = message;
        return res;
    }

    private static String describeErrors(List<Database.Error> errors) {
        List<String> messages = new List<String>();
        if (errors != null) {
            for (Database.Error err : errors) {
                messages.add(err.getMessage());
            }
        }
        return messages.isEmpty()
            ? 'The gift could not be staged for import.'
            : String.join(messages, ' ');
    }
}
