public with sharing class RecurringGiftService {

    public class RecurringGiftException extends Exception {}

    public class GiftRequest {
        public Id contactId;
        public Decimal amount;
        public Integer dayOfMonth;    // 1-31
        public Date startDate;
        public Integer installments;  // null or 0 = no end date
        public String paymentMethod;  // 'Credit Card', 'ACH' or 'Check'
    }

    private static final Integer LAST_DAY_OF_MONTH = 31;

    /**
     * Creates one Enhanced Recurring Donation (npe03__Recurring_Donation__c) per request,
     * in request order, and returns the new Ids in that same order.
     *
     * NPSP generates the installment Opportunities itself - this service performs no
     * Opportunity DML. Bulk safe: a single validation pass (no DML) plus one insert.
     */
    public static List<Id> createMonthlyGifts(List<GiftRequest> requests) {
        List<Id> result = new List<Id>();
        if (requests == null || requests.isEmpty()) {
            return result;
        }

        // 1) Validate everything up front, before any DML.
        for (Integer i = 0; i < requests.size(); i++) {
            GiftRequest req = requests[i];
            String label = 'requests[' + i + ']';

            if (req == null) {
                throw new RecurringGiftException(label + ': request must not be null.');
            }
            if (req.contactId == null) {
                throw new RecurringGiftException(label + ': contactId is required.');
            }
            if (req.amount == null || req.amount <= 0) {
                throw new RecurringGiftException(label + ': amount must be greater than zero.');
            }
            if (req.dayOfMonth == null || req.dayOfMonth < 1 || req.dayOfMonth > LAST_DAY_OF_MONTH) {
                throw new RecurringGiftException(label + ': dayOfMonth must be between 1 and 31.');
            }
            if (req.startDate == null) {
                throw new RecurringGiftException(label + ': startDate is required.');
            }
        }

        // 2) Build the recurring donations (no DML yet).
        List<npe03__Recurring_Donation__c> recurringDonations =
            new List<npe03__Recurring_Donation__c>();

        for (GiftRequest req : requests) {
            recurringDonations.add(buildRecurringDonation(req));
        }

        // 3) Single DML statement for the whole batch.
        insert recurringDonations;

        for (npe03__Recurring_Donation__c rd : recurringDonations) {
            result.add(rd.Id);
        }
        return result;
    }

    private static npe03__Recurring_Donation__c buildRecurringDonation(GiftRequest req) {
        Boolean useLastDayOfMonth = (req.dayOfMonth == LAST_DAY_OF_MONTH);
        Boolean isOpenEnded = (req.installments == null || req.installments == 0);

        npe03__Recurring_Donation__c rd = new npe03__Recurring_Donation__c();

        // Donor
        rd.npe03__Contact__c = req.contactId;
        rd.npe03__Organization__c = null;

        // Amount and schedule
        rd.npe03__Amount__c = req.amount;
        rd.npe03__Installment_Period__c = 'Monthly';
        rd.npsp__RecurringType__c = 'Open';
        rd.npsp__InstallmentFrequency__c = 1;

        // Day of month; day 31 = "last day of the month" via NPSP's own option.
        rd.npsp__Day_of_Month__c = req.dayOfMonth;
        rd.npsp__Always_Use_Last_Day_Of_Month__c = useLastDayOfMonth;

        // Dates
        rd.npsp__StartDate__c = req.startDate;
        rd.npe03__Date_Established__c = req.startDate;
        rd.npe03__Next_Payment_Date__c = req.startDate;

        // End date / installments
        if (isOpenEnded) {
            rd.npsp__RecurringType__c = 'Open';
            rd.npsp__EndDate__c = null;
            rd.npe03__Installments__c = null;
            rd.npe03__Open_Ended_Status__c = 'Open';
            rd.npe03__Schedule_Type__c = 'Donate';
        } else {
            rd.npsp__RecurringType__c = 'Fixed';
            rd.npsp__EndDate__c = req.startDate.addMonths(req.installments - 1);
            rd.npe03__Installments__c = req.installments;
            rd.npe03__Open_Ended_Status__c = 'Closed';
            rd.npe03__Schedule_Type__c = 'Donate';
        }

        // Status and payment method
        rd.npsp__Status__c = 'Active';
        rd.npsp__PaymentMethod__c = req.paymentMethod;

        return rd;
    }
}
