/**
 * Service used by the event check-in app to register a family in one go.
 *
 * Works against the NPSP Household Account model with automatic household naming:
 * NPSP owns Account.Name and the household greeting fields for the HH_Account record
 * type, so this service deliberately never sets the account name itself.
 */
public with sharing class HouseholdService {

    /** DeveloperName of the NPSP Household Account record type — the Id is never hard-coded. */
    private static final String HH_RECORD_TYPE_DEVELOPER_NAME = 'HH_Account';

    /**
     * Creates one brand-new NPSP Household Account, inserts every member Contact into it,
     * flags the first contact as the household's primary contact and returns the Account Id.
     *
     * Exactly one Account row is ever created by this call: the Account is created first,
     * so NPSP's per-contact auto-household creation never fires (every Contact already has
     * an AccountId when it is inserted), and no empty household is left behind if the
     * member Contacts cannot be saved.
     *
     * Bulk-safe/efficient: 1 account insert + 1 bulk contact insert + 1 account update.
     *
     * @param members non-empty list of brand-new Contacts (no Id, no AccountId)
     * @return the Id of the newly created NPSP Household Account
     * @throws IllegalArgumentException if members is null, empty, or contains null entries
     */
    public static Id createHousehold(List<Contact> members) {
        if (members == null || members.isEmpty()) {
            throw new IllegalArgumentException('Household members must be a non-empty list of Contacts.');
        }
        for (Contact member : members) {
            if (member == null) {
                throw new IllegalArgumentException('Household members must not contain null entries.');
            }
        }

        Id householdRecordTypeId = getHouseholdRecordTypeId();

        // Name is intentionally left unset: NPSP's automatic household naming fills in the
        // Account name and the household greetings for records with the HH_Account type.
        Account household = new Account(RecordTypeId = householdRecordTypeId);
        insert household;

        try {
            // Route all members to the single household first, so NPSP does not
            // auto-create one household Account per contact.
            for (Contact member : members) {
                member.AccountId = household.Id;
            }
            insert members;
        } catch (Exception e) {
            // Never leave an empty household behind if the members could not be saved.
            try {
                delete household;
            } catch (Exception cleanupFailure) {
                // Best effort only — rethrow the original failure below.
            }
            throw e;
        }

        // NPSP stores a household's primary contact on Account.npe01__One2OneContact__c.
        household.npe01__One2OneContact__c = members[0].Id;
        update household;

        return household.Id;
    }

    /**
     * Resolves the NPSP Household Account record type Id by DeveloperName so that
     * no record type Id is hard-coded.
     */
    private static Id getHouseholdRecordTypeId() {
        Schema.RecordTypeInfo householdRecordType =
            Schema.SObjectType.Account
                .getRecordTypeInfosByDeveloperName()
                .get(HH_RECORD_TYPE_DEVELOPER_NAME);

        if (householdRecordType == null
                || !householdRecordType.isActive()
                || !householdRecordType.isAvailable()) {
            throw new IllegalArgumentException(
                'NPSP Household Account record type "' +
                HH_RECORD_TYPE_DEVELOPER_NAME +
                '" is not available in this org.'
            );
        }

        return householdRecordType.getRecordTypeId();
    }
}
