public with sharing class SoftCreditService {

    public class SoftCreditException extends Exception { }

    public class SoftCreditRequest {
        public Id opportunityId;
        public Id contactId;
        public Decimal amount;
        public String role;
    }

    private static final String CONTACT_NAME_FIELD = 'npsp__Contact_Name__c';

    private static String keyOf(Id opportunityId, Id contactId) {
        return String.valueOf(opportunityId) + '#' + String.valueOf(contactId);
    }

    public static void addPartialSoftCredits(List<SoftCreditRequest> requests) {
        if (requests == null || requests.isEmpty()) {
            return;
        }

        // Normalise the input and collect the Ids we need to query.
        List<SoftCreditRequest> work = new List<SoftCreditRequest>();
        Set<Id> opportunityIds = new Set<Id>();
        Set<Id> contactIds = new Set<Id>();
        for (SoftCreditRequest request : requests) {
            if (request == null) {
                continue;
            }
            work.add(request);
            if (request.opportunityId != null) {
                opportunityIds.add(request.opportunityId);
            }
            if (request.contactId != null) {
                contactIds.add(request.contactId);
            }
        }
        if (work.isEmpty()) {
            return;
        }

        // SOQL 1: the opportunities being credited.
        Map<Id, Opportunity> opportunitiesById = new Map<Id, Opportunity>(
            [SELECT Id, Amount, npsp__Primary_Contact__c
               FROM Opportunity
              WHERE Id IN :opportunityIds]
        );

        // SOQL 2: contact roles already present on those opportunities.
        Map<String, List<OpportunityContactRole>> rolesByKey =
            new Map<String, List<OpportunityContactRole>>();
        for (OpportunityContactRole role : [
                SELECT Id, OpportunityId, ContactId, Role
                  FROM OpportunityContactRole
                 WHERE OpportunityId IN :opportunityIds
                   AND ContactId IN :contactIds]) {
            String key = keyOf(role.OpportunityId, role.ContactId);
            if (!rolesByKey.containsKey(key)) {
                rolesByKey.put(key, new List<OpportunityContactRole>());
            }
            rolesByKey.get(key).add(role);
        }

        // SOQL 3: partial soft credits that already exist on those opportunities.
        Map<String, npsp__Partial_Soft_Credit__c> creditsByContactKey =
            new Map<String, npsp__Partial_Soft_Credit__c>();
        Map<String, npsp__Partial_Soft_Credit__c> creditsByRoleKey =
            new Map<String, npsp__Partial_Soft_Credit__c>();
        for (npsp__Partial_Soft_Credit__c credit : [
                SELECT Id, npsp__Opportunity__c, npsp__Contact__c, npsp__Contact_Role_ID__c
                  FROM npsp__Partial_Soft_Credit__c
                 WHERE npsp__Opportunity__c IN :opportunityIds]) {
            if (credit.npsp__Contact__c != null) {
                creditsByContactKey.put(
                    keyOf(credit.npsp__Opportunity__c, credit.npsp__Contact__c), credit);
            }
            if (String.isNotBlank(credit.npsp__Contact_Role_ID__c)) {
                creditsByRoleKey.put(
                    String.valueOf(credit.npsp__Opportunity__c) + '#' + credit.npsp__Contact_Role_ID__c,
                    credit);
            }
        }

        // Validate the whole call before any DML so nothing is changed on failure.
        for (SoftCreditRequest request : work) {
            Opportunity opportunity = (request.opportunityId == null)
                ? null
                : opportunitiesById.get(request.opportunityId);
            if (opportunity == null) {
                throw new SoftCreditException(
                    'Opportunity not found: ' + request.opportunityId);
            }
            if (request.contactId == null) {
                throw new SoftCreditException(
                    'A contactId is required for opportunity ' + request.opportunityId + '.');
            }
            if (opportunity.npsp__Primary_Contact__c == request.contactId) {
                throw new SoftCreditException(
                    'Contact ' + request.contactId + ' is the primary contact of opportunity '
                    + request.opportunityId + ' and cannot receive a partial soft credit.');
            }
            if (request.amount == null || request.amount <= 0) {
                throw new SoftCreditException(
                    'The soft credit amount must be a positive number for opportunity '
                    + request.opportunityId + '.');
            }
            if (opportunity.Amount != null && request.amount > opportunity.Amount) {
                throw new SoftCreditException(
                    'The soft credit amount ' + request.amount
                    + ' exceeds the amount of opportunity ' + request.opportunityId + '.');
            }
        }

        // Ensure each fundraiser ends up with exactly one contact role on the
        // opportunity whose Role equals the requested role.  An existing role is
        // reused (and its Role updated when it differs) so no duplicate role rows
        // are created; only contacts without any role get a new row.
        List<OpportunityContactRole> rolesToInsert = new List<OpportunityContactRole>();
        List<OpportunityContactRole> rolesToUpdate = new List<OpportunityContactRole>();
        Map<String, OpportunityContactRole> chosenRoleByKey =
            new Map<String, OpportunityContactRole>();

        for (SoftCreditRequest request : work) {
            String key = keyOf(request.opportunityId, request.contactId);
            OpportunityContactRole chosen = null;
            List<OpportunityContactRole> candidates = rolesByKey.get(key);
            if (candidates != null && !candidates.isEmpty()) {
                for (OpportunityContactRole candidate : candidates) {
                    if (candidate.Role == request.role) {
                        chosen = candidate;
                        break;
                    }
                }
                if (chosen == null) {
                    chosen = candidates[0];
                }
            }
            if (chosen == null) {
                chosen = new OpportunityContactRole(
                    OpportunityId = request.opportunityId,
                    ContactId = request.contactId,
                    Role = request.role
                );
                rolesToInsert.add(chosen);
            } else if (chosen.Role != request.role) {
                chosen.Role = request.role;
                rolesToUpdate.add(chosen);
            }
            chosenRoleByKey.put(key, chosen);
        }

        if (!rolesToInsert.isEmpty()) {
            insert rolesToInsert;   // DML 1
        }
        if (!rolesToUpdate.isEmpty()) {
            update rolesToUpdate;   // DML 2
        }

        // npsp__Contact_Name__c is only written when the org exposes it as a
        // writable (non-formula, non-auto-number) field; formula/derived variants
        // are left to calculate themselves.
        Boolean populateContactName = false;
        Boolean contactNameIsReference = false;
        Schema.SObjectField contactNameField =
            Schema.SObjectType.npsp__Partial_Soft_Credit__c.fields.getMap()
                .get(CONTACT_NAME_FIELD);
        if (contactNameField != null) {
            Schema.DescribeFieldResult describe = contactNameField.getDescribe();
            populateContactName = describe.isCreateable()
                && !describe.isCalculated()
                && !describe.isAutoNumber();
            contactNameIsReference = (describe.getType() == Schema.DisplayType.REFERENCE);
        }
        Map<Id, Contact> contactsById = new Map<Id, Contact>();
        if (populateContactName && !contactNameIsReference) {
            // SOQL 4 (only issued when a writable contact name field really exists).
            contactsById = new Map<Id, Contact>(
                [SELECT Id, Name FROM Contact WHERE Id IN :contactIds]);
        }

        // One partial soft credit per opportunity/contact: update the existing
        // record when there is one, otherwise create it, always linked to the
        // contact role that carries the requested role name.
        List<npsp__Partial_Soft_Credit__c> creditsToInsert =
            new List<npsp__Partial_Soft_Credit__c>();
        List<npsp__Partial_Soft_Credit__c> creditsToUpdate =
            new List<npsp__Partial_Soft_Credit__c>();

        for (SoftCreditRequest request : work) {
            String key = keyOf(request.opportunityId, request.contactId);
            OpportunityContactRole chosen = chosenRoleByKey.get(key);

            npsp__Partial_Soft_Credit__c credit = creditsByContactKey.get(key);
            if (credit == null) {
                credit = creditsByRoleKey.get(
                    String.valueOf(request.opportunityId) + '#' + chosen.Id);
            }

            if (credit == null) {
                credit = new npsp__Partial_Soft_Credit__c(
                    npsp__Opportunity__c = request.opportunityId,
                    npsp__Contact__c = request.contactId,
                    npsp__Amount__c = request.amount,
                    npsp__Role_Name__c = request.role,
                    npsp__Contact_Role_ID__c = chosen.Id
                );
                creditsToInsert.add(credit);
            } else {
                credit.npsp__Opportunity__c = request.opportunityId;
                credit.npsp__Contact__c = request.contactId;
                credit.npsp__Amount__c = request.amount;
                credit.npsp__Role_Name__c = request.role;
                credit.npsp__Contact_Role_ID__c = chosen.Id;
                creditsToUpdate.add(credit);
            }

            if (populateContactName) {
                if (contactNameIsReference) {
                    credit.put(CONTACT_NAME_FIELD, request.contactId);
                } else if (contactsById.containsKey(request.contactId)) {
                    credit.put(CONTACT_NAME_FIELD, contactsById.get(request.contactId).Name);
                }
            }
        }

        if (!creditsToInsert.isEmpty()) {
            insert creditsToInsert;   // DML 3
        }
        if (!creditsToUpdate.isEmpty()) {
            update creditsToUpdate;   // DML 4
        }
    }
}
