/**
 * Read-only service behind the employee directory component.
 *
 * Sharing : the class is declared `with sharing`, so the query honours the
 *           org-wide default (Private) and only returns the FB_Employee__c rows
 *           that are shared with the running user. Nothing is queried
 *           "without sharing".
 *
 * FLS     : only the fields the running user can actually read are added to the
 *           SELECT clause, so an unreadable field is ABSENT from the returned
 *           records (never present-with-null) and is never fetched at all;
 *           stripInaccessible() is applied as a second, independent guard.
 *           No WITH SECURITY_ENFORCED / USER_MODE is used, so partial FLS can
 *           never make the method throw.
 *
 * Access  : a user without object-level read access to FB_Employee__c gets an
 *           empty list instead of an exception.
 */
public with sharing class EmployeeDirectoryService {

    public static List<FB_Employee__c> getDirectory() {

        Schema.DescribeSObjectResult objectDescribe = Schema.SObjectType.FB_Employee__c;

        // No object-level read access (or the object is not queryable): nothing to show.
        if (!objectDescribe.isAccessible() || !objectDescribe.isQueryable()) {
            return new List<FB_Employee__c>();
        }

        // Candidate projection: standard fields + the three directory fields.
        List<Schema.DescribeFieldResult> candidateFields = new List<Schema.DescribeFieldResult>{
            Schema.SObjectType.FB_Employee__c.fields.Id,
            Schema.SObjectType.FB_Employee__c.fields.Name,
            Schema.SObjectType.FB_Employee__c.fields.Department__c,
            Schema.SObjectType.FB_Employee__c.fields.Salary__c,
            Schema.SObjectType.FB_Employee__c.fields.Personal_Email__c
        };

        List<String> selectableFields = new List<String>();

        for (Schema.DescribeFieldResult fieldDescribe : candidateFields) {
            if (fieldDescribe.isAccessible()) {
                selectableFields.add(fieldDescribe.getName());
            }
        }

        // Nothing readable at field level: return an empty list rather than failing.
        if (selectableFields.isEmpty()) {
            return new List<FB_Employee__c>();
        }

        // Field API names come from a fixed, hardcoded list - no user input reaches
        // the statement, so there is no SOQL injection surface.
        String soql =
            'SELECT ' + String.join(selectableFields, ',') +
            ' FROM ' + objectDescribe.getName() +
            ' ORDER BY Name ASC';

        // Dynamic SOQL executed inside a `with sharing` class -> sharing enforced.
        // stripInaccessible() guarantees any field the running user cannot read is
        // removed from the returned records instead of being present-but-null.
        List<SObject> readableRows = Security.stripInaccessible(
            AccessType.READABLE,
            Database.query(soql)
        ).getRecords();

        List<FB_Employee__c> directory = new List<FB_Employee__c>();
        for (SObject row : readableRows) {
            directory.add((FB_Employee__c) row);
        }

        return directory;
    }
}
