public with sharing class TA_Account_CreateOnboardingTask implements TriggerAction.AfterInsert {
	private static final String CUSTOMER_DIRECT_TYPE = 'Customer - Direct';
	private static final String CUSTOMER_CHANNEL_TYPE = 'Customer - Channel';
	private static final String ONBOARDING_SUBJECT = 'Onboard new customer';
	private static final String STATUS_NOT_STARTED = 'Not Started';
	private static final String PRIORITY_NORMAL = 'Normal';
	private static final Integer DAYS_UNTIL_DUE = 7;

	public void afterInsert(List<SObject> triggerNew) {
		List<Account> accounts = (List<Account>) triggerNew;
		List<Task> tasksToInsert = new List<Task>();
		Date dueDate = Date.today().addDays(DAYS_UNTIL_DUE);

		for (Account account : accounts) {
			if (!isQualifyingCustomer(account)) {
				continue;
			}
			tasksToInsert.add(
				new Task(
					Subject = ONBOARDING_SUBJECT,
					WhatId = account.Id,
					OwnerId = account.OwnerId,
					ActivityDate = dueDate,
					Status = STATUS_NOT_STARTED,
					Priority = PRIORITY_NORMAL
				)
			);
		}

		if (!tasksToInsert.isEmpty()) {
			insert tasksToInsert;
		}
	}

	private static Boolean isQualifyingCustomer(Account account) {
		return account.Type == CUSTOMER_DIRECT_TYPE || account.Type == CUSTOMER_CHANNEL_TYPE;
	}
}
