```apex
public with sharing class OpportunityErpSyncFinalizer implements TriggerAction.DmlFinalizer {
	/*
	 * The framework invokes EVERY registered DML finalizer at the end of every
	 * DML operation it handles, whatever the sObject, therefore:
	 *  - the collected Ids are drained first: if nothing was collected for this
	 *    operation, no job is enqueued at all (e.g. an update that does not
	 *    change StageName, or DML on an unrelated object);
	 *  - draining before enqueueing guarantees exactly one job per DML operation,
	 *    carrying only the Ids of that operation: the 200 + 50 chunks of a single
	 *    insert all feed the same collection, which is flushed once;
	 *  - a following DML statement of the same transaction starts with an empty
	 *    collection and therefore gets its own, separate job.
	 *
	 * No DML may be performed here - only the queueable is enqueued.
	 */
	public void execute(FinalizerHandler.Context context) {
		Set<Id> opportunityIds = TA_Opportunity_CollectForErpSync.getIdsToSync();
		TA_Opportunity_CollectForErpSync.clearIdsToSync();

		if (opportunityIds == null || opportunityIds.isEmpty()) {
			return;
		}

		System.enqueueJob(new OpportunityErpSyncJob(opportunityIds));
	}
}
