```apex
public without sharing class TA_Contact_Queries {
	/*
	 * Singleton query locator for the Contact before-insert trigger actions.
	 * The Service inner class loads the parent accounts exactly once per trigger
	 * execution; the other actions read the shared map and never query.
	 */
	public Map<Id, Account> accountsById { get; private set; }

	private static TA_Contact_Queries instance;

	private TA_Contact_Queries() {
		this.accountsById = new Map<Id, Account>();
	}

	public static TA_Contact_Queries getInstance() {
		if (instance == null) {
			instance = new TA_Contact_Queries();
		}
		return instance;
	}

	public class Service implements TriggerAction.BeforeInsert {
		public void beforeInsert(List<SObject> triggerNew) {
			Set<Id> accountIds = new Set<Id>();
			for (SObject record : triggerNew) {
				Id accountId = (Id) record.get('AccountId');
				if (accountId != null) {
					accountIds.add(accountId);
				}
			}

			TA_Contact_Queries queries = getInstance();
			// Always reload: later DML in the same transaction may involve
			// accounts that were not present in a previous execution.
			queries.accountsById = accountIds.isEmpty()
				? new Map<Id, Account>()
				: new Map<Id, Account>(
					[
						SELECT
							Id,
							BillingStreet,
							BillingCity,
							BillingPostalCode,
							BillingCountry,
							AccountSource
						FROM Account
						WHERE Id IN :accountIds
					]
				);
		}
	}
}
